package com.dpworld.fms.api;
import java.util.Map;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class AssignmentExpiryScheduler{private final JdbcTemplate jdbc;public AssignmentExpiryScheduler(JdbcTemplate jdbc){this.jdbc=jdbc;}@Scheduled(fixedDelayString="${dpwfms.automation.assignment-reconciliation-ms:30000}")@Transactional public void expire(){for(Map<String,Object>a:jdbc.queryForList("SELECT * FROM parking_assignments WHERE status IN ('PROPOSED','ASSIGNED','EN_ROUTE') AND expires_at<now() FOR UPDATE SKIP LOCKED")){jdbc.update("UPDATE parking_assignments SET status='EXPIRED',completed_at=now(),version=version+1 WHERE id=?",a.get("id"));jdbc.update("UPDATE parking_spaces SET status='AVAILABLE',reserved=FALSE,current_asset_id=NULL,reservation_expiry=NULL,version=version+1 WHERE id=?",a.get("parking_space_id"));jdbc.update("UPDATE assets SET current_job_id=NULL,availability_status='AVAILABLE',version=version+1 WHERE id=?",a.get("asset_id"));}for(Map<String,Object>a:jdbc.queryForList("SELECT * FROM charging_assignments WHERE status IN ('PROPOSED','ASSIGNED','EN_ROUTE') AND expires_at<now() FOR UPDATE SKIP LOCKED")){jdbc.update("UPDATE charging_assignments SET status='EXPIRED',completed_at=now(),version=version+1 WHERE id=?",a.get("id"));if(a.get("slot_id")!=null)jdbc.update("UPDATE service_bays SET status='AVAILABLE',current_asset_id=NULL,reservation_expiry=NULL,version=version+1 WHERE id=?",a.get("slot_id"));jdbc.update("UPDATE assets SET current_job_id=NULL,availability_status='AVAILABLE',version=version+1 WHERE id=?",a.get("asset_id"));}}}
